[CmdletBinding()]
param([Parameter(Mandatory)][string]$ResolvedComposeJson,[Parameter(Mandatory)][string]$BuildImageManifest,[Parameter(Mandatory)][string]$SbomPath,[Parameter(Mandatory)][string]$VulnerabilitySarif,[Parameter(Mandatory)][string]$SignatureReport,[Parameter(Mandatory)][string]$ProvenanceReport,[string]$OutputPath='release-security-evidence.json')
$ErrorActionPreference='Stop';$inputs=@($ResolvedComposeJson,$BuildImageManifest,$SbomPath,$VulnerabilitySarif,$SignatureReport,$ProvenanceReport);foreach($p in $inputs){if(-not(Test-Path $p)){throw "Evidence missing: $p"}}
$c=Get-Content -Raw $ResolvedComposeJson|ConvertFrom-Json;$runtime=@($c.services.PSObject.Properties|%{[string]$_.Value.image}|?{$_});$built=@(Get-Content $BuildImageManifest|%{[string]$_}|?{$_});$images=@($runtime+$built|sort -Unique);$bad=@($images|?{$_-notmatch'@sha256:[0-9a-f]{64}$'});if($bad){throw "Runtime or build-only images not digest pinned: $($bad-join', ')"};$commit=[string](git rev-parse HEAD)
$sarif=Get-Content -Raw $VulnerabilitySarif|ConvertFrom-Json;$findings=@($sarif.runs|%{$_.results}|?{$_});if($findings){throw "Vulnerability gate failed with $($findings.Count) parsed finding(s)."}
$signatures=@(Get-Content -Raw $SignatureReport|ConvertFrom-Json);$provenance=@(Get-Content -Raw $ProvenanceReport|ConvertFrom-Json);foreach($image in $images){$sig=@($signatures|?{$_.image-eq$image-and$_.verified-eq$true});if($sig.Count-ne1-or-not$sig[0].identity-or-not$sig[0].issuer){throw "Signature gate failed: $image"};$prov=@($provenance|?{$_.image-eq$image-and$_.verified-eq$true});if($prov.Count-ne1-or-not$prov[0].builder_id-or$prov[0].source_commit-ne$commit){throw "Provenance gate failed: $image"}}
function Get-EvidenceHash($p){[string](Get-FileHash -Algorithm SHA256 $p).Hash.ToLowerInvariant()};$bound=@();foreach($p in $inputs){$bound+=[pscustomobject]@{path=[string]$p;sha256=[string](Get-EvidenceHash $p)}};$m=[pscustomobject]@{schema_version=2;created_at=[string][DateTimeOffset]::UtcNow.ToString('o');git_commit=$commit;images=[string[]]$images;runtime_images=[string[]]@($runtime|sort -Unique);build_only_images=[string[]]@($built|?{$_-notin$runtime}|sort -Unique);parsed_vulnerability_findings=[int]$findings.Count;inputs=[object[]]$bound};$m|ConvertTo-Json -Depth 8|Set-Content $OutputPath -Encoding utf8;Write-Output "Verified and bound $($images.Count) signed, provenance-backed images."
